steps.code:
# Get contacts for each friend in the CSV
names = ["Cory", "Edwin", "Glenn", "Anita", "Debra", "Morgan", "Kevin", "Kristin", "Melissa", "Norman", "Robin"]
contacts = {}
for name in names:
    result = apis.phone.search_contacts(access_token=phone_token, query=name, page_limit=20)
    # result is a list of contacts; we'll take the first match with that first name
    for c in result:
        if c["first_name"].lower() == name.lower():
            contacts[name] = c
            break
print(contacts)

